  1396  void Runtime::initCharacterStrings() {
  1397    GCScope gc(this);
  1398    auto marker = gc.createMarker();
  1399    charStrings_.reserve(256);
  1400    for (char16_t ch = 0; ch < 256; ++ch) {
  1401      gc.flushToMarker(marker);
  1402      charStrings_.push_back(allocateCharacterString(ch).getHermesValue());
  1403    }
  1404  }
