  1406  Handle<StringPrimitive> Runtime::allocateCharacterString(char16_t ch) {
  1407    // This can in theory throw when called out of initialization phase.
  1408    // However there is only that many character strings and in practice this
  1409    // is not a problem.  Note that we allocate these as "long-lived" objects,
  1410    // so we don't have to scan the charStrings_ array in
  1411    // young-generation collections.
  1412
  1413    PinnedHermesValue strRes;
  1414    if (LLVM_LIKELY(ch < 128)) {
  1415      strRes = ignoreAllocationFailure(
  1416          StringPrimitive::createLongLived(this, ASCIIRef(ch)));
  1417    } else {
  1418      strRes = ignoreAllocationFailure(
  1419          StringPrimitive::createLongLived(this, UTF16Ref(ch)));
  1420    }
  1421    return makeHandle<StringPrimitive>(strRes);
  1422  }
